import { useEffect, useState, useCallback, useRef } from "react";
import { QRCodeSVG } from "qrcode.react";
import { getQrToken } from "../../api/studentApi";
import { useToast, apiErrorMessage } from "../../context/ToastContext";

const VALID_SECONDS = 90;
const REFRESH_AT = 10; // refresh a bit before actual expiry, so staff never scans a dead code

export default function PayAtCounter() {
  const [token, setToken] = useState(null);
  const [secondsLeft, setSecondsLeft] = useState(VALID_SECONDS);
  const [loading, setLoading] = useState(true);
  const toast = useToast();
  const tickRef = useRef(null);

  const fetchToken = useCallback(() => {
    setLoading(true);
    getQrToken()
      .then((res) => {
        setToken(res.data.data.token);
        setSecondsLeft(res.data.data.expiresInSeconds || VALID_SECONDS);
      })
      .catch((err) => toast.error(apiErrorMessage(err, "Could not generate QR code")))
      .finally(() => setLoading(false));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => { fetchToken(); }, [fetchToken]);

  useEffect(() => {
    tickRef.current = setInterval(() => {
      setSecondsLeft((s) => {
        if (s <= REFRESH_AT) {
          fetchToken();
          return VALID_SECONDS;
        }
        return s - 1;
      });
    }, 1000);
    return () => clearInterval(tickRef.current);
  }, [fetchToken]);

  const pct = Math.max(0, Math.min(100, (secondsLeft / VALID_SECONDS) * 100));

  return (
    <>
      <div className="page-head">
        <div>
          <span className="eyebrow">Counter Checkout</span>
          <h1>Show this to canteen staff</h1>
          <p className="desc">This code refreshes automatically and can only be used once.</p>
        </div>
      </div>

      <div className="card card-pad" style={{ maxWidth: 380, margin: "0 auto", textAlign: "center" }}>
        <div style={{
          display: "inline-flex", padding: 20, background: "#fff",
          borderRadius: 16, border: "1px solid var(--line)", marginBottom: 20,
        }}>
          {loading && !token && <div style={{ width: 220, height: 220 }} />}
          {token && <QRCodeSVG value={token} size={220} level="M" />}
        </div>

        <div style={{
          height: 4, borderRadius: 999, background: "var(--paper-dim)",
          overflow: "hidden", marginBottom: 10,
        }}>
          <div style={{
            height: "100%", width: `${pct}%`, background: "#B9862B",
            transition: "width 1s linear",
          }} />
        </div>

        <p style={{ fontSize: 13, color: "var(--text-muted)" }}>
          {loading ? "Generating code…" : `Refreshes in ${secondsLeft}s`}
        </p>

        <button className="btn btn-ghost btn-sm" onClick={fetchToken} style={{ marginTop: 12 }}>
          Refresh now
        </button>
      </div>
    </>
  );
}
